import{_ as i,a0 as l,w as p,s as a,I as n,x as e,a1 as s,A as r,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux有問必答：如何在CentOS7上改變網絡接口名 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在CentOS7上改變網絡接口名 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在CentOS7上改變網絡接口名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在CentOS7上改變網絡接口名 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140925 Linux FAQs with Answers--How to change a network interface name on CentOS 7","title":"Linux有問必答：如何在CentOS7上改變網絡接口名","tag":"201410","desc":""},"relativePath":"201410/20140925 Linux FAQs with Answers--How to change a network interface name on CentOS 7.md","filePath":"[post].md"}'),d={name:"201410/20140925 Linux FAQs with Answers--How to change a network interface name on CentOS 7.md"};function m(f,t,g,C,x,L){const o=l("Link");return p(),a("div",null,[t[14]||(t[14]=n("h1",{id:"linux有問必答-如何在centos7上改變網絡接口名",tabindex:"-1"},[e("Linux有問必答：如何在CentOS7上改變網絡接口名 "),n("a",{class:"header-anchor",href:"#linux有問必答-如何在centos7上改變網絡接口名","aria-label":"Permalink to “Linux有問必答：如何在CentOS7上改變網絡接口名”"},"​")],-1)),t[15]||(t[15]=n("blockquote",null,[n("p",null,[n("strong",null,"提問"),e(": 在CentOS7，我想將分配的網絡接口名更改為別的名字。有什麼合適的方法來來重命名CentOS或RHEL7的網絡接口？")])],-1)),t[16]||(t[16]=n("p",null,"傳統上，Linux的網絡接口被枚舉為eth[0123...]，但這些名稱並不一定符合實際的硬件插槽，PCI位置，USB接口數量等，這引入了一個不可預知的命名問題（例如，由於不確定的設備探測行為），這可能會導致不同的網絡配置錯誤（例如，由無意的接口改名引起的禁止接口或者防火牆旁路）。基於MAC地址的udev規則在虛擬化的環境中並不有用，這裏的MAC地址如端口數量一樣無常。",-1)),n("p",null,[t[1]||(t[1]=e("CentOS/RHEL6引入了",-1)),s(o,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/6/html/Deployment_Guide/appe-Consistent_Network_Device_Naming.html"},{default:r(()=>[...t[0]||(t[0]=[e("一致和可預測的網絡設備命名",-1)])]),_:1}),t[2]||(t[2]=e("網絡接口的方法。這些特性可以唯一地確定網絡接口的名稱以使定位和區分設備更容易，並且在這樣一種方式下，無論是否重啓機器、過了多少時間、或者改變硬件，其名字都是持久不變的。然而，這種命名規則並不是默認在CentOS/RHEL6上開啓。",-1))]),t[17]||(t[17]=u(`<p>從CentOS/RHEL7起，這種可預見的命名規則變成了默認。根據這一規則，接口名稱被自動基於固件，拓撲結構和位置信息來確定。現在，即使添加或移除網絡設備，接口名稱仍然保持固定，而無需重新枚舉，和壞掉的硬件可以無縫替換。</p><pre><code>* 基於接口類型的兩個字母前綴:
*   en -- 以太網
*   sl -- 串行線路IP (slip)
*   wl -- wlan
*   ww -- wwan
*
* 名字類型:
*   b&lt;number&gt;                             -- BCMA總線和新書
*   ccw&lt;name&gt;                             -- CCW總線組名
*   o&lt;index&gt;                              -- 車載設備的索引號
*   s&lt;slot&gt;[f&lt;function&gt;][d&lt;dev_port&gt;]     -- 熱插拔插槽索引號
*   x&lt;MAC&gt;                                -- MAC 地址
*   [P&lt;domain&gt;]p&lt;bus&gt;s&lt;slot&gt;[f&lt;function&gt;][d&lt;dev_port&gt;]
*                                         -- PCI 位置
*   [P&lt;domain&gt;]p&lt;bus&gt;s&lt;slot&gt;[f&lt;function&gt;][u&lt;port&gt;][..]1[i&lt;interface&gt;]
*                                         -- USB端口號鏈
</code></pre><p>新的命名方案的一個小的缺點是接口名稱相比傳統名稱有點難以閲讀。例如，你可能會發現像enp0s3名字。再者，你再也無法來控制接口名了。</p><p><img src="https://farm4.staticflickr.com/3854/15294996451_fa731ce12c_z.jpg" alt=""></p><p>如果由於某種原因，你喜歡舊的方式，並希望能夠選擇任意名稱分配給CentOS/ RHEL7的設備，你需要重寫默認的可預測的命名規則，定義基於MAC地址udev規則。</p><p><strong>下面是如何在CentOS或RHEL7命名網絡接口。</strong></p><p>首先，讓我們來禁用該可預測命名規則。對於這一點，你可以在啓動時傳遞“net.ifnames=0”的內核參數。這是通過編輯/etc/default/grub並加入“net.ifnames=0”到GRUB_CMDLINE_LINUX變量來實現的。</p><p><img src="https://farm4.staticflickr.com/3898/15315687725_c82fbef5bc_z.jpg" alt=""></p><p>然後運行這條命令來重新生成GRUB配置並更新內核參數。</p><pre><code>$ sudo grub2-mkconfig -o /boot/grub2/grub.cfg 
</code></pre><p><img src="https://farm4.staticflickr.com/3909/15128981250_72f45633c1_z.jpg" alt=""></p><p>接下來，編輯（或創建）一個udev的網絡命名規則文件（/etc/udev/rules.d/70-persistent-net.rules），並添加下面一行。更換成你自己的MAC地址（08:00:27:a9:7a:e1）和接口（sushi）。</p><pre><code> $ sudo vi /etc/udev/rules.d/70-persistent-net.rules 
</code></pre><hr><pre><code>SUBSYSTEM==&quot;net&quot;, ACTION==&quot;add&quot;, DRIVERS==&quot;?*&quot;, ATTR{address}==&quot;08:00:27:a9:7a:e1&quot;, ATTR{type}==&quot;1&quot;, KERNEL==&quot;eth*&quot;, NAME=&quot;sushi&quot;
</code></pre><p>最後，重啓電腦並驗證新的接口名。</p><p><img src="https://farm4.staticflickr.com/3861/15111594847_14e0c5a00d_z.jpg" alt=""></p><p>請注意，配置重命名後的接口仍然是你的責任。如果網絡配置（例如，IPv4設置，防火牆規則）是基於舊名稱（變更前）的，則需要更新的網絡配置以反映更改的名稱。</p><hr>`,19)),n("p",null,[t[4]||(t[4]=e("via: ",-1)),s(o,{href:"http://ask.xmodulo.com/change-network-interface-name-centos7.html"},{default:r(()=>[...t[3]||(t[3]=[e("http://ask.xmodulo.com/change-network-interface-name-centos7.html",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=e("譯者：",-1)),s(o,{href:"https://github.com/geekpi"},{default:r(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[8]||(t[8]=e(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原創翻譯，",-1)),s(o,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[e("Linux中國",-1)])]),_:1}),t[13]||(t[13]=e(" 榮譽推出",-1))])])}const _=i(d,[["render",m]]);export{T as __pageData,_ as default};
